def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'
    if n >= 98:
        return 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    overall_opp = opp_c / n

    window = min(10, n)
    recent = history[-window:]
    recent_opp_c = sum(1 for a, b in recent if b == 'C')
    recent_opp = recent_opp_c / window

    last_my, last_opp = history[-1]

    def_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            def_streak += 1
        else:
            break

    if def_streak >= 3:
        return 'D'

    if overall_opp < 0.3 or recent_opp < 0.3:
        return 'D'

    if last_opp == 'D':
        if overall_opp > 0.7 or recent_opp > 0.55:
            return 'C'
        else:
            return 'D'

    return 'C'
